package com.hbm.machine.foundry.crucible;
import com.hbm.api.machine.ICopiable;
import com.hbm.heat.HeatSource;
import com.hbm.machine.foundry.*;
import com.hbm.material.*;
import com.hbm.multiblock.DummyableBlock;
import com.hbm.pollution.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.entity.player.*;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.*;
/** Complete source heat pull, item capture/smelting, ratio gating, material alloying and two safe pouring mouths. */
public final class CrucibleBlockEntity extends ThermalMachine implements FoundryAcceptor,ICopiable {
 public int heat,progress;public String recipe="null";public final List<MaterialStack> recipeStack=new ArrayList<>(),wasteStack=new ArrayList<>();
 public CrucibleBlockEntity(BlockPos pos,BlockState state){super(CrucibleContent.CRUCIBLE_ENTITY.get(),pos,state,10);}
 @Override protected String title(){return "container.machineCrucible";}@Override public int getMaxStackSize(){return 1;}
 public List<CrucibleRecipe> recipes(){return level==null?List.of():CrucibleRecipeConfig.recipes(level.getRecipeManager());}public CrucibleRecipe loadedRecipe(){return recipes().stream().filter(r->r.name().equals(recipe)).findFirst().orElse(null);}
 public void selectRecipe(String selection){recipe=selection;setChanged();}
 @Override public AbstractContainerMenu createMenu(int id,Inventory inventory,Player player){return new ThermalMenu(id,inventory,this,worldPosition,false);}
 public static void tick(Level level,BlockPos pos,BlockState state,CrucibleBlockEntity self){if(level instanceof ServerLevel server)self.serverTick(server);else if((!self.recipeStack.isEmpty()||!self.wasteStack.isEmpty())&&level.getGameTime()%10==0)com.hbm.particle.LegacyFluidEffects.tower(level,pos.getX()+.5,pos.getY()+1,pos.getZ()+.5,new com.hbm.particle.LegacyFluidEffects.Tower(10,.75F,3.5F,100+level.random.nextInt(20)).color(0x202020));}
 private void serverTick(ServerLevel server){
  pullHeat();if(server.getGameTime()%5==0)for(var item:server.getEntitiesOfClass(ItemEntity.class,new AABB(worldPosition.getX()-.5,worldPosition.getY()+.5,worldPosition.getZ()-.5,worldPosition.getX()+1.5,worldPosition.getY()+1,worldPosition.getZ()+1.5))){if(item.isRemoved())continue;var stack=item.getItem();if(smeltable(stack))for(int i=1;i<10;i++)if(slots.get(i).isEmpty()){if(stack.getCount()==1){slots.set(i,stack.copy());item.discard();item.setPickUpDelay(60);break;}slots.set(i,stack.copyWithCount(1));stack.shrink(1);setChanged();}}
  int mass=quanta(recipeStack,null)+quanta(wasteStack,null);double fill=(double)mass/(CrucibleConfig.recipeCapacity+CrucibleConfig.wasteCapacity)*.875;for(var entity:server.getEntitiesOfClass(LivingEntity.class,new AABB(worldPosition.getX()-.5,worldPosition.getY()+.5,worldPosition.getZ()-.5,worldPosition.getX()+1.5,worldPosition.getY()+.5+fill,worldPosition.getZ()+1.5))){entity.hurt(server.damageSources().lava(),5);entity.igniteForSeconds(5);}
  if(!smelt())progress=0;alloy();if(!wasteStack.isEmpty())pourStack(server,wasteStack,DummyableBlock.facing(getBlockState()).getOpposite());
  if(!recipeStack.isEmpty()){var selected=loadedRecipe();var drainable=new ArrayList<MaterialStack>();if(selected==null)drainable.addAll(recipeStack);else for(var material:recipeStack)for(var output:selected.output())if(material.material==output.material){drainable.add(material);break;}pourStack(server,drainable,DummyableBlock.facing(getBlockState()));}
  recipeStack.removeIf(stack->stack.amount<=0);wasteStack.removeIf(stack->stack.amount<=0);sync(25);
 }
 private void pourStack(ServerLevel server,List<MaterialStack> stacks,Direction dir){Vec3[] impact={Vec3.ZERO};MaterialStack poured=FoundryPouring.pourFullStack(server,worldPosition.getX()+.5+dir.getStepX()*1.875,worldPosition.getY()+.25,worldPosition.getZ()+.5+dir.getStepZ()*1.875,6,true,stacks,HbmMaterials.shape("NUGGET").q(3),impact);if(poured!=null)FoundryStreamPacket.send(server,new Vec3(worldPosition.getX()+.5+dir.getStepX()*1.875,worldPosition.getY(),worldPosition.getZ()+.5+dir.getStepZ()*1.875),poured.material.moltenColor(),dir,Math.max(1F,worldPosition.getY()-(float)(Math.ceil(impact[0].y)-.875)),.625F,.625F);PollutionSystem.increment(server,worldPosition,PollutionType.SOOT,PollutionSystem.SOOT_PER_SECOND/20F);}
 private void pullHeat(){if(heat>=CrucibleConfig.maxHeat)return;var below=level.getBlockEntity(worldPosition.below());if(below instanceof HeatSource source){int difference=source.getHeatStored()-heat;if(difference==0)return;difference=Math.min(difference,CrucibleConfig.maxHeat-heat);if(difference>0){difference=(int)Math.ceil(difference*CrucibleConfig.diffusion);source.useUpHeat(difference);heat+=difference;if(heat>CrucibleConfig.maxHeat)heat=CrucibleConfig.maxHeat;return;}}heat=Math.max(heat-Math.max(heat/1000,1),0);}
 private boolean smelt(){if(heat<CrucibleConfig.maxHeat/2)return false;int slot=firstSmeltable();if(slot<0)return false;int delta=heat-CrucibleConfig.maxHeat/2;delta*=.05;progress+=delta;heat-=delta;if(progress>=CrucibleConfig.processHeat){progress=0;var selected=loadedRecipe();for(var material:smeltingMaterials(slots.get(slot),false)){boolean isRecipe=selected!=null&&(quanta(selected.input(),material.material)>0||quanta(selected.output(),material.material)>0);add(isRecipe?recipeStack:wasteStack,material);}removeItem(slot,1);}return true;}
 private void alloy(){var selected=loadedRecipe();if(selected==null||level.getGameTime()%selected.frequency()>0)return;for(var stack:selected.input())if(quanta(recipeStack,stack.material)<stack.amount)return;for(var stack:recipeStack)stack.amount-=quanta(selected.input(),stack.material);for(var output:selected.output())add(recipeStack,output);}
 public int firstSmeltable(){for(int i=1;i<10;i++)if(!slots.get(i).isEmpty()&&smeltable(slots.get(i)))return i;return -1;}
 private List<MaterialStack> smeltingMaterials(ItemStack stack,boolean maximum){double rate=com.hbm.ore.OreProcessing.rate(stack);return HbmMaterials.getSmeltingMaterialsFromItem(stack).stream().map(m->new MaterialStack(m.material,maximum?com.hbm.ore.OreProcessing.maximumCount(m.amount,rate):com.hbm.ore.OreProcessing.count(m.amount,rate,level.random))).toList();}
 public boolean smeltable(ItemStack stack){var materials=smeltingMaterials(stack,true);if(materials.isEmpty())return false;var selected=loadedRecipe();boolean matches=selected==null;int recipeContent=selected==null?0:selected.inputAmount(),recipeAmount=quanta(recipeStack,null),wasteAmount=quanta(wasteStack,null);for(var material:materials){int required=selected==null?0:quanta(selected.input(),material.material);if(selected!=null&&quanta(selected.output(),material.material)>0){recipeAmount+=material.amount;matches=true;continue;}if(required==0)wasteAmount+=material.amount;else{int maximum=required*CrucibleConfig.recipeCapacity/recipeContent,stored=quanta(recipeStack,material.material);matches=true;recipeAmount+=material.amount;if(stored+material.amount>maximum)return false;}}return recipeAmount<=CrucibleConfig.recipeCapacity&&wasteAmount<=CrucibleConfig.wasteCapacity&&matches;}
 public static int quanta(List<MaterialStack> stacks,NtmMaterial material){int amount=0;for(var stack:stacks){if(stack.material==material)return stack.amount;if(material==null)amount+=stack.amount;}return amount;}
 private static void add(List<MaterialStack> stacks,MaterialStack input){for(var stack:stacks)if(stack.material==input.material){stack.amount+=input.amount;return;}stacks.add(input.copy());}
 @Override public boolean canPlaceItem(int slot,ItemStack stack){return smeltable(stack);}@Override public int[] getSlotsForFace(Direction side){return new int[]{1,2,3,4,5,6,7,8,9};}
 @Override public boolean canAcceptPartialFlow(Direction side,MaterialStack stack){return false;}@Override public MaterialStack flow(Direction side,MaterialStack stack){return null;}
 @Override public boolean canAcceptPartialPour(Vec3 hit,Direction side,MaterialStack stack){var selected=loadedRecipe();if(selected==null)return quanta(wasteStack,null)<CrucibleConfig.wasteCapacity;int required=quanta(selected.input(),stack.material),maximum=required*CrucibleConfig.recipeCapacity/selected.inputAmount(),stored=quanta(recipeStack,stack.material);return stored<maximum&&quanta(recipeStack,null)<CrucibleConfig.recipeCapacity;}
 @Override public MaterialStack pour(Vec3 hit,Direction side,MaterialStack stack){var selected=loadedRecipe();if(selected==null){int current=quanta(wasteStack,null);if(current+stack.amount<=CrucibleConfig.wasteCapacity){add(wasteStack,stack);setChanged();return null;}int amount=CrucibleConfig.wasteCapacity-current;add(wasteStack,new MaterialStack(stack.material,amount));setChanged();return new MaterialStack(stack.material,stack.amount-amount);}int maximum=quanta(selected.input(),stack.material)*CrucibleConfig.recipeCapacity/selected.inputAmount(),amount=Math.min(maximum-quanta(recipeStack,stack.material),CrucibleConfig.recipeCapacity-quanta(recipeStack,null));amount=Math.min(amount,stack.amount);if(amount<=0)return stack;add(recipeStack,new MaterialStack(stack.material,amount));setChanged();return amount<stack.amount?new MaterialStack(stack.material,stack.amount-amount):null;}
 private static void saveMaterials(CompoundTag tag,String key,List<MaterialStack> list){int[] values=new int[list.size()*2];for(int i=0;i<list.size();i++){values[i*2]=list.get(i).material.id();values[i*2+1]=list.get(i).amount;}tag.putIntArray(key,values);}private static void loadMaterials(CompoundTag tag,String key,List<MaterialStack> list){list.clear();int[] values=tag.getIntArray(key);for(int i=0;i<values.length/2;i++){var material=HbmMaterials.byId(values[i*2]);if(material!=null)list.add(new MaterialStack(material,values[i*2+1]));}}
 @Override protected void saveMachine(CompoundTag tag){tag.putString("recipe",recipe);tag.putInt("heat",heat);tag.putInt("progress",progress);saveMaterials(tag,"rec",recipeStack);saveMaterials(tag,"was",wasteStack);}@Override protected void loadMachine(CompoundTag tag){recipe=tag.getString("recipe");heat=tag.getInt("heat");progress=tag.getInt("progress");loadMaterials(tag,"rec",recipeStack);loadMaterials(tag,"was",wasteStack);}
 @Override public List<ProgressView> progressBars(){var bars=new ArrayList<ProgressView>();bars.add(new ProgressView("jade.hbm.crucible.heat",heat,CrucibleConfig.maxHeat,0xE69B51));bars.add(new ProgressView("jade.hbm.crucible.recipe_material",quanta(recipeStack,null),CrucibleConfig.recipeCapacity,0xFF8E42));bars.add(new ProgressView("jade.hbm.crucible.waste_material",quanta(wasteStack,null),CrucibleConfig.wasteCapacity,0x997555));if(progress>0||firstSmeltable()>=0)bars.add(new ProgressView("jade.hbm.processing",progress,CrucibleConfig.processHeat,0x71C78B));return bars;}
 @Override public CompoundTag getSettings(Level level,BlockPos pos){var tag=new CompoundTag();var ids=new ArrayList<Integer>();for(var stack:recipeStack)ids.add(stack.material.id());for(var stack:wasteStack)ids.add(stack.material.id());if(!ids.isEmpty())tag.putIntArray("matFilter",ids.stream().mapToInt(Integer::intValue).toArray());return tag;}@Override public void pasteSettings(CompoundTag tag,int index,Level level,Player player,BlockPos pos){}@Override public String[] infoForDisplay(Level level,BlockPos pos){return java.util.stream.Stream.concat(recipeStack.stream(),wasteStack.stream()).map(s->s.material.descriptionId()).toArray(String[]::new);}
}
